1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Labour Market Portal — Dashboard</title>
7	  <meta name="description" content="Equatorial Guinea Ministry of Labour private-sector employment dashboard prototype">
8	
9	  <!-- Geist Sans + Mono -->
10	  <link rel="preconnect" href="https://cdn.jsdelivr.net">
11	  <style>
12	    @font-face {
13	      font-family: 'Geist Sans';
14	      src: url('https://cdn.jsdelivr.net/npm/geist@1.2.2/dist/fonts/geist-sans/Geist-Variable.woff2') format('woff2');
15	      font-weight: 100 900;
16	      font-style: normal;
17	      font-display: swap;
18	    }
19	    @font-face {
20	      font-family: 'Geist Mono';
21	      src: url('https://cdn.jsdelivr.net/npm/geist@1.2.2/dist/fonts/geist-mono/GeistMono-Variable.woff2') format('woff2');
22	      font-weight: 100 900;
23	      font-style: normal;
24	      font-display: swap;
25	    }
26	  </style>
27	
28	  <!-- Phosphor Icons Bold -->
29	  <link rel="stylesheet" href="https://unpkg.com/@phosphor-icons/web@2.1.1/src/bold/style.css">
30	
31	  <!-- Pretext fallback -->
32	  <script type="module">
33	    import { prepare, layout } from 'https://esm.sh/@chenglou/pretext';
34	    window.Pretext = { prepare, layout };
35	  </script>
36	
37	  <style>
38	    :root {
39	      --canvas: #ffffff;
40	      --surface: #f9f9f8;
41	      --bone: #f7f6f3;
42	      --border: #eaeaea;
43	      --text: #111111;
44	      --text-secondary: #787774;
45	      --text-tertiary: #a5a29a;
46	      --accent: #1E3A5F;
47	      --accent-hover: #172E4C;
48	      --success-bg: #edf3ec;
49	      --success-text: #346538;
50	      --warning-bg: #fbf3db;
51	      --warning-text: #956400;
52	      --error-bg: #fdebec;
53	      --error-text: #9f2f2d;
54	      --info-bg: #e1f3fe;
55	      --info-text: #1f6c9f;
56	      --radius-sm: 6px;
57	      --radius-md: 10px;
58	      --radius-lg: 14px;
59	      --shadow-hover: 0 2px 8px rgba(0, 0, 0, 0.04);
60	      --font-sans: 'Geist Sans', 'SF Pro Display', -apple-system, BlinkMacSystemFont, sans-serif;
61	      --font-mono: 'Geist Mono', 'SF Mono', ui-monospace, monospace;
62	      --space-xs: 4px;
63	      --space-sm: 8px;
64	      --space-md: 16px;
65	      --space-lg: 24px;
66	      --space-xl: 32px;
67	      --space-2xl: 48px;
68	    }
69	
70	    * { box-sizing: border-box; }
71	
72	    html, body {
73	      margin: 0;
74	      padding: 0;
75	      height: 100%;
76	      font-family: var(--font-sans);
77	      color: var(--text);
78	      background: var(--bone);
79	      -webkit-font-smoothing: antialiased;
80	      -moz-osx-font-smoothing: grayscale;
81	    }
82	
83	    button, input, select, textarea {
84	      font-family: 'Inter', sans-serif;
85	      font-size: inherit;
86	    }
87	
88	    /* App shell */
89	    .app {
90	      display: grid;
91	      grid-template-columns: 260px 1fr;
92	      min-height: 100dvh;
93	    }
94	
95	    /* Sidebar */
96	    .sidebar {
97	      position: sticky;
98	      top: 0;
99	      height: 100dvh;
100	      background: var(--canvas);
101	      border-right: 1px solid var(--border);
102	      display: flex;
103	      flex-direction: column;
104	      padding: var(--space-lg);
105	      overflow-y: auto;
106	    }
107	
108	    .brand {
109	      display: flex;
110	      align-items: center;
111	      gap: var(--space-md);
112	      margin-bottom: var(--space-2xl);
113	    }
114	
115	    .brand-mark {
116	      width: 36px;
117	      height: 36px;
118	      border-radius: var(--radius-sm);
119	      background: var(--accent);
120	      display: grid;
121	      place-items: center;
122	      color: white;
123	      font-size: 18px;
124	    }
125	
126	    .brand-name {
127	      font-size: 15px;
128	      font-weight: 600;
129	      letter-spacing: -0.01em;
130	      line-height: 1.2;
131	    }
132	
133	    .brand-sub {
134	      font-size: 12px;
135	      color: var(--text-secondary);
136	      font-family: var(--font-mono);
137	    }
138	
139	    .nav-group + .nav-group { margin-top: var(--space-xl); }
140	
141	    .nav-label {
142	      font-size: 11px;
143	      font-weight: 600;
144	      text-transform: uppercase;
145	      letter-spacing: 0.08em;
146	      color: var(--text-tertiary);
147	      padding: 0 var(--space-md);
148	      margin-bottom: var(--space-sm);
149	    }
150	
151	    .nav-list {
152	      list-style: none;
153	      margin: 0;
154	      padding: 0;
155	      display: flex;
156	      flex-direction: column;
157	      gap: 2px;
158	    }
159	
160	    .nav-item {
161	      display: flex;
162	      align-items: center;
163	      gap: var(--space-md);
164	      padding: 10px var(--space-md);
165	      border-radius: var(--radius-md);
166	      color: var(--text-secondary);
167	      font-size: 14px;
168	      font-weight: 500;
169	      cursor: pointer;
170	      transition: background 150ms ease, color 150ms ease;
171	      text-decoration: none;
172	    }
173	
174	    .nav-item:hover {
175	      background: var(--surface);
176	      color: var(--text);
177	    }
178	
179	    .nav-item.is-active {
180	      background: var(--bone);
181	      color: var(--text);
182	      font-weight: 600;
183	    }
184	
185	    .nav-item i { font-size: 18px; }
186	
187	    .sidebar-foot {
188	      margin-top: auto;
189	      padding-top: var(--space-lg);
190	      border-top: 1px solid var(--border);
191	    }
192	
193	    .user-mini {
194	      display: flex;
195	      align-items: center;
196	      gap: var(--space-md);
197	      padding: var(--space-md);
198	      border-radius: var(--radius-md);
199	      border: 1px solid var(--border);
200	      background: var(--surface);
201	    }
202	
203	    .user-avatar {
204	      width: 34px;
205	      height: 34px;
206	      border-radius: var(--radius-sm);
207	      background: var(--text);
208	      color: var(--canvas);
209	      display: grid;
210	      place-items: center;
211	      font-size: 12px;
212	      font-weight: 700;
213	      font-family: var(--font-mono);
214	    }
215	
216	    .user-name { font-size: 13px; font-weight: 600; }
217	    .user-role { font-size: 12px; color: var(--text-secondary); }
218	
219	    /* Main */
220	    .main {
221	      padding: var(--space-2xl);
222	      max-width: 1440px;
223	    }
224	
225	    .page-header {
226	      display: flex;
227	      align-items: flex-start;
228	      justify-content: space-between;
229	      gap: var(--space-lg);
230	      margin-bottom: var(--space-2xl);
231	    }
232	
233	    .page-title {
234	      font-size: 28px;
235	      font-weight: 600;
236	      letter-spacing: -0.02em;
237	      margin: 0 0 6px;
238	    }
239	
240	    .page-subtitle {
241	      font-size: 14px;
242	      color: var(--text-secondary);
243	      margin: 0;
244	    }
245	
246	    .header-actions {
247	      display: flex;
248	      align-items: center;
249	      gap: var(--space-md);
250	    }
251	
252	    .btn {
253	      display: inline-flex;
254	      align-items: center;
255	      gap: 8px;
256	      padding: 10px 16px;
257	      border-radius: var(--radius-sm);
258	      font-size: 14px;
259	      font-weight: 600;
260	      cursor: pointer;
261	      border: 1px solid transparent;
262	      transition: transform 120ms ease, background 150ms ease, border-color 150ms ease;
263	    }
264	
265	    .btn:active { transform: scale(0.98); }
266	
267	    .btn-primary {
268	      background: var(--accent);
269	      color: white;
270	    }
271	
272	    .btn-primary:hover { background: var(--accent-hover); }
273	
274	    .btn-secondary {
275	      background: var(--canvas);
276	      color: var(--text);
277	      border-color: var(--border);
278	    }
279	
280	    .btn-secondary:hover { background: var(--surface); }
281	
282	    /* Filter bar */
283	    .filter-bar {
284	      display: flex;
285	      flex-wrap: wrap;
286	      align-items: center;
287	      gap: var(--space-md);
288	      padding: var(--space-md);
289	      background: var(--canvas);
290	      border: 1px solid var(--border);
291	      border-radius: var(--radius-md);
292	      margin-bottom: var(--space-2xl);
293	    }
294	
295	    .filter-group {
296	      display: flex;
297	      flex-direction: column;
298	      gap: var(--space-xs);
299	      min-width: 140px;
300	      flex: 1;
301	    }
302	
303	    .filter-label {
304	      font-size: 11px;
305	      font-weight: 600;
306	      text-transform: uppercase;
307	      letter-spacing: 0.06em;
308	      color: var(--text-tertiary);
309	    }
310	
311	    .filter-select {
312	      padding: 8px 10px;
313	      border: 1px solid var(--border);
314	      border-radius: var(--radius-sm);
315	      background: var(--surface);
316	      color: var(--text);
317	      font-size: 14px;
318	      cursor: pointer;
319	    }
320	
321	    .filter-meta {
322	      margin-left: auto;
323	      display: flex;
324	      align-items: center;
325	      gap: var(--space-md);
326	      font-size: 13px;
327	      color: var(--text-secondary);
328	      font-family: var(--font-mono);
329	    }
330	
331	    /* KPI grid */
332	    .kpi-grid {
333	      display: grid;
334	      grid-template-columns: repeat(4, 1fr);
335	      gap: var(--space-lg);
336	      margin-bottom: var(--space-2xl);
337	    }
338	
339	    .kpi-tile {
340	      background: var(--canvas);
341	      border: 1px solid var(--border);
342	      border-radius: var(--radius-md);
343	      padding: var(--space-lg);
344	      display: flex;
345	      flex-direction: column;
346	      gap: var(--space-sm);
347	      transition: box-shadow 200ms ease;
348	    }
349	
350	    .kpi-tile:hover { box-shadow: var(--shadow-hover); }
351	
352	    .kpi-label {
353	      font-size: 13px;
354	      font-weight: 500;
355	      color: var(--text-secondary);
356	    }
357	
358	    .kpi-value {
359	      font-size: 36px;
360	      font-weight: 600;
361	      letter-spacing: -0.03em;
362	      font-family: var(--font-mono);
363	      line-height: 1;
364	    }
365	
366	    .kpi-delta {
367	      display: inline-flex;
368	      align-items: center;
369	      gap: 4px;
370	      font-size: 12px;
371	      font-weight: 600;
372	      font-family: var(--font-mono);
373	    }
374	
375	    .kpi-delta.positive { color: var(--success-text); }
376	    .kpi-delta.negative { color: var(--error-text); }
377	
378	    .kpi-context {
379	      font-size: 12px;
380	      color: var(--text-tertiary);
381	    }
382	
383	    /* Bento sections */
384	    .section {
385	      margin-bottom: var(--space-2xl);
386	    }
387	
388	    .section-header {
389	      display: flex;
390	      align-items: baseline;
391	      justify-content: space-between;
392	      margin-bottom: var(--space-lg);
393	    }
394	
395	    .section-title {
396	      font-size: 18px;
397	      font-weight: 600;
398	      letter-spacing: -0.01em;
399	      margin: 0;
400	    }
401	
402	    .section-note {
403	      font-size: 13px;
404	      color: var(--text-secondary);
405	    }
406	
407	    .bento {
408	      display: grid;
409	      gap: var(--space-lg);
410	    }
411	
412	    .bento-3 { grid-template-columns: repeat(3, 1fr); }
413	    .bento-2 { grid-template-columns: repeat(2, 1fr); }
414	    .bento-mixed {
415	      grid-template-columns: 2fr 1fr;
416	    }
417	
418	    .card {
419	      background: var(--canvas);
420	      border: 1px solid var(--border);
421	      border-radius: var(--radius-md);
422	      padding: var(--space-lg);
423	    }
424	
425	    .card-title {
426	      font-size: 14px;
427	      font-weight: 600;
428	      margin: 0 0 var(--space-md);
429	      color: var(--text);
430	    }
431	
432	    .bar-list {
433	      display: flex;
434	      flex-direction: column;
435	      gap: var(--space-md);
436	    }
437	
438	    .bar-item {
439	      display: grid;
440	      grid-template-columns: 1fr auto;
441	      gap: var(--space-md);
442	      align-items: center;
443	    }
444	
445	    .bar-label {
446	      font-size: 13px;
447	      color: var(--text);
448	      font-weight: 500;
449	    }
450	
451	    .bar-value {
452	      font-size: 13px;
453	      font-family: var(--font-mono);
454	      color: var(--text-secondary);
455	      text-align: right;
456	    }
457	
458	    .bar-track {
459	      grid-column: 1 / -1;
460	      height: 6px;
461	      background: var(--bone);
462	      border-radius: 9999px;
463	      overflow: hidden;
464	    }
465	
466	    .bar-fill {
467	      height: 100%;
468	      background: var(--accent);
469	      border-radius: 9999px;
470	    }
471	
472	    .bar-fill.muted { background: var(--text-tertiary); opacity: 0.5; }
473	
474	    /* Table */
475	    .data-table {
476	      width: 100%;
477	      border-collapse: collapse;
478	      font-size: 13px;
479	    }
480	
481	    .data-table th {
482	      text-align: left;
483	      padding: 10px 12px;
484	      font-weight: 600;
485	      color: var(--text-secondary);
486	      border-bottom: 1px solid var(--border);
487	      font-size: 11px;
488	      text-transform: uppercase;
489	      letter-spacing: 0.06em;
490	    }
491	
492	    .data-table td {
493	      padding: 12px;
494	      border-bottom: 1px solid var(--border);
495	      color: var(--text);
496	    }
497	
498	    .data-table tr:last-child td { border-bottom: none; }
499	
500	    /* Status badges */
501	    .badge {
502	      display: inline-flex;
503	      align-items: center;
504	      padding: 4px 10px;
505	      border-radius: 9999px;
506	      font-size: 11px;
507	      font-weight: 600;
508	      text-transform: uppercase;
509	      letter-spacing: 0.05em;
510	    }
511	
512	    .badge-success { background: var(--success-bg); color: var(--success-text); }
513	    .badge-warning { background: var(--warning-bg); color: var(--warning-text); }
514	    .badge-error { background: var(--error-bg); color: var(--error-text); }
515	    .badge-info { background: var(--info-bg); color: var(--info-text); }
516	
517	    /* Funnel */
518	    .funnel {
519	      display: flex;
520	      flex-direction: column;
521	      gap: var(--space-sm);
522	    }
523	
524	    .funnel-row {
525	      display: grid;
526	      grid-template-columns: 1fr auto;
527	      align-items: center;
528	      gap: var(--space-md);
529	      padding: 10px 0;
530	      border-bottom: 1px solid var(--border);
531	    }
532	
533	    .funnel-row:last-child { border-bottom: none; }
534	
535	    .funnel-stage {
536	      display: flex;
537	      align-items: center;
538	      gap: var(--space-md);
539	    }
540	
541	    .funnel-bar {
542	      height: 8px;
543	      background: var(--accent);
544	      border-radius: 9999px;
545	      min-width: 4px;
546	    }
547	
548	    .funnel-label {
549	      font-size: 13px;
550	      color: var(--text);
551	    }
552	
553	    .funnel-count {
554	      font-family: var(--font-mono);
555	      font-size: 14px;
556	      font-weight: 600;
557	    }
558	
559	    /* Activity */
560	    .activity-list {
561	      display: flex;
562	      flex-direction: column;
563	    }
564	
565	    .activity-row {
566	      display: grid;
567	      grid-template-columns: 130px 1fr auto;
568	      gap: var(--space-md);
569	      align-items: flex-start;
570	      padding: 14px 0;
571	      border-bottom: 1px solid var(--border);
