1254	    // Pretext-powered text reflow for metric tiles and card titles
1255	    const { prepare, layout } = window.Pretext;
1256	    await document.fonts.ready;
1257	
1258	    const pretextElements = document.querySelectorAll('[data-pretext]');
1259	    const prepared = new Map();
1260	
1261	    for (const el of pretextElements) {
1262	      const font = getComputedStyle(el).font;
1263	      prepared.set(el, prepare(el.textContent, font));
1264	    }
1265	
1266	    function relayout() {
1267	      for (const [el, handle] of prepared) {
1268	        const lineHeight = parseFloat(getComputedStyle(el).lineHeight);
1269	        const { height } = layout(handle, el.clientWidth, lineHeight);
1270	        el.style.height = `${height}px`;
1271	      }
1272	    }
1273	
1274	    const ro = new ResizeObserver(() => relayout());
1275	    ro.observe(document.body);
1276	    relayout();
1277	
1278	    for (const el of pretextElements) {
1279	      if (el.contentEditable === 'true') {
1280	        new MutationObserver(() => {
1281	          const font = getComputedStyle(el).font;
1282	          prepared.set(el, prepare(el.textContent, font));
1283	          relayout();
1284	        }).observe(el, { characterData: true, subtree: true, childList: true });
1285	      }
1286	    }
