911	  <script>
912	    /* i18n:STR:start */
913	    const STR = {
914	      suspendTitle: "Suspend Member Company",
915	      returnTitle: "Return Membership Application",
916	      suspendConfirm: "Are you sure you want to suspend access for {name}? A comment is required to proceed.",
917	      returnConfirm: "Are you sure you want to return the membership application for {name}? A comment is required to proceed.",
918	      commentRequired: "Please enter a comment before submitting.",
919	      statusSuspended: "Suspended",
920	      statusRejected: "Rejected",
921	      actionActivate: "Activate",
922	      actionSuspend: "Suspend",
923	      statusVerified: "Verified",
924	      reinvitedName: "Re-invited {name}",
925	      actionProcessedSuccess: "Action processed successfully. Comment logged: \"{comment}\"",
926	      fillAllFields: "Please fill out all fields.",
927	      invitedJustNow: "Invited Just Now",
928	      statusInvited: "Invited",
929	      invitationResent: "Invitation re-sent",
930	      actionResend: "Resend"
931	    };
932	    /* i18n:STR:end */
933	    const fmt = (s, v = {}) => s.replace(/\{(\w+)\}/g, (_, k) => v[k] ?? '{' + k + '}');
934	
935	    let activeModRow = null;
936	    let activeModType = '';
937	    let activeModName = '';
938	
939	    function openModal(id) {
940	      document.getElementById(id).classList.add('is-open');
941	    }
942	
943	    function closeModal(id) {
944	      document.getElementById(id).classList.remove('is-open');
945	      if(id === 'moderation-modal') {
946	        document.getElementById('mod-comment').value = '';
947	      }
948	    }
949	
950	    function filterEntities() {
951	      const sector = document.getElementById('filter-sector').value.toLowerCase();
952	      const status = document.getElementById('filter-status').value.toLowerCase();
953	      const size = document.getElementById('filter-size').value.toLowerCase();
954	      const rows = document.querySelectorAll('#entities-table tbody tr');
955	
956	      rows.forEach(row => {
957	        const rowSector = row.getAttribute('data-sector').toLowerCase();
958	        const rowStatus = row.getAttribute('data-status').toLowerCase();
959	        const rowSize = row.getAttribute('data-size').toLowerCase();
960	
961	        const matchSector = (sector === 'all' || rowSector === sector);
962	        const matchStatus = (status === 'all' || rowStatus === status);
963	        const matchSize = (size === 'all' || rowSize === size);
964	
965	        if(matchSector && matchStatus && matchSize) {
966	          row.style.display = '';
967	        } else {
968	          row.style.display = 'none';
969	        }
970	      });
971	    }
972	
973	    function openModeration(type, entityName) {
974	      activeModType = type;
975	      activeModName = entityName;
976	      const title = type === 'suspend' ? STR.suspendTitle : STR.returnTitle;
977	      const desc = type === 'suspend'
978	        ? fmt(STR.suspendConfirm, { name: entityName })
979	        : fmt(STR.returnConfirm, { name: entityName });
980	
981	      document.getElementById('mod-title').textContent = title;
982	      document.getElementById('mod-desc').textContent = desc;
983	
984	      const triggerBtn = event.currentTarget;
985	      activeModRow = triggerBtn.closest('tr');
986	
987	      openModal('moderation-modal');
988	    }
989	
990	    function submitModeration() {
991	      const comment = document.getElementById('mod-comment').value.trim();
992	      if(!comment) {
993	        alert(STR.commentRequired);
994	        return;
995	      }
996	
997	      // Perform simulated state change
998	      if (activeModRow) {
999	        const statusTd = activeModRow.querySelector('td:nth-child(5)');
1000	        const actionTd = activeModRow.querySelector('td:nth-child(7)');
1001	
1002	        if (activeModType === 'suspend') {
1003	          statusTd.innerHTML = `<span class="badge badge-error">${STR.statusSuspended}</span>`;
1004	          activeModRow.setAttribute('data-status', 'suspended');
1005	          actionTd.innerHTML = `<button class="btn btn-secondary" style="padding: 6px 12px; font-size:12px;" onclick="changeStatus(this, '${STR.statusVerified}', 'badge-success', '${STR.actionSuspend}')">${STR.actionActivate}</button>`;
1006	        } else if (activeModType === 'reject') {
1007	          statusTd.innerHTML = `<span class="badge badge-error">${STR.statusRejected}</span>`;
1008	          activeModRow.setAttribute('data-status', 'rejected');
1009	          actionTd.innerHTML = `<button class="btn btn-secondary" style="padding: 6px 12px; font-size:12px;" onclick="alert('${fmt(STR.reinvitedName, { name: activeModName })}')">${STR.actionResend}</button>`;
1010	        }
1011	      }
1012	
1013	      closeModal('moderation-modal');
1014	      alert(fmt(STR.actionProcessedSuccess, { comment }));
1015	    }
1016	
1017	    function changeStatus(btn, statusLabel, badgeClass, nextActionLabel) {
1018	      // statusLabel is the localized text shown in the badge. All current
1019	      // callers transition a row to the "verified" state, so the internal
1020	      // data-status key (used by the sector/status/size filters above) and
1021	      // the branch below are keyed off that fixed, locale-invariant string
1022	      // rather than off statusLabel — comparing statusLabel to a literal
1023	      // would silently stop matching once statusLabel is translated.
1024	      const row = btn.closest('tr');
1025	      const statusTd = row.querySelector('td:nth-child(5)');
1026	      const actionTd = row.querySelector('td:nth-child(7)');
1027	
1028	      statusTd.innerHTML = `<span class="badge ${badgeClass}">${statusLabel}</span>`;
1029	      row.setAttribute('data-status', 'verified');
1030	
1031	      actionTd.innerHTML = `<button class="btn btn-secondary" style="padding: 6px 12px; font-size:12px;" onclick="openModeration('suspend', '${row.querySelector('strong').textContent}')">${nextActionLabel}</button>`;
1032	    }
1033	
1034	    function submitInvite() {
1035	      const name = document.getElementById('invite-name').value.trim();
1036	      const email = document.getElementById('invite-email').value.trim();
1037	      const sector = document.getElementById('invite-sector-sel').value;
1038	
1039	      if(!name || !email) {
1040	        alert(STR.fillAllFields);
1041	        return;
1042	      }
1043	
1044	      // Add to table dynamically
1045	      const tableBody = document.querySelector('#entities-table tbody');
1046	      const newRow = document.createElement('tr');
1047	      newRow.setAttribute('data-sector', sector.toLowerCase());
1048	      newRow.setAttribute('data-status', 'invited');
1049	      newRow.setAttribute('data-size', '1–49');
1050	
1051	      newRow.innerHTML = `
1052	        <td><strong>${name}</strong><br><small style="color:var(--text-secondary)">${STR.invitedJustNow}</small></td>
1053	        <td>${email}</td>
1054	        <td>${sector}</td>
1055	        <td>1–49</td>
1056	        <td><span class="badge badge-warning">${STR.statusInvited}</span></td>
1057	        <td>
1058	          <div class="progress-container">
1059	            <div class="progress-bar"><div class="progress-fill" style="width: 0%"></div></div>
1060	            <span class="progress-label">0%</span>
1061	          </div>
1062	        </td>
1063	        <td style="text-align: right;">
1064	          <button class="btn btn-secondary" style="padding: 6px 12px; font-size:12px;" onclick="alert('${STR.invitationResent}')">${STR.actionResend}</button>
1065	        </td>
1066	      `;
1067	
1068	      tableBody.insertBefore(newRow, tableBody.firstChild);
1069	      closeModal('invite-modal');
1070	
1071	      // Reset fields
1072	      document.getElementById('invite-name').value = '';
1073	      document.getElementById('invite-email').value = '';
1074	    }
1075	  </script>
