def build_overlay(subtitle1, subtitle2, cursor_moves, hf_id):
    # cursor_moves: list of dicts with x,y,duration for the two moves; hold durations fixed
    fade_in = 0.5
    move1_dur = cursor_moves[0]['duration']
    hold1 = cursor_moves[0]['hold']
    move2_dur = cursor_moves[1]['duration']
    hold2 = cursor_moves[1]['hold']
