def build_composition(src_path, out_path, beat_id, hf_id, subtitle1, subtitle2, cursor_moves):
    with open(src_path, 'r', encoding='utf-8') as f:
        src = f.read()

    src = strip_gate(src)

    # split head/body
    body_open_match = re.search(r'<body>', src)
    body_close_match = re.search(r'</body>', src)
    if not body_open_match or not body_close_match:
        raise RuntimeError(f"couldn't find body tags in {src_path}")

    head_part = src[:body_open_match.end()]  # includes "<body>"
    body_inner = src[body_open_match.end():body_close_match.start()]
    tail_part = src[body_close_match.start():]  # "</body>\n</html>\n"

    wrapper_open = f'\n<div data-hf-id="{hf_id}" data-composition-id="{beat_id}" data-width="1920" data-height="1080" data-duration="10">'
    overlay = build_overlay(subtitle1, subtitle2, cursor_moves, hf_id)
    wrapper_close = '\n</div>\n'

    result = head_part + wrapper_open + body_inner + overlay + wrapper_close + tail_part

    with open(out_path, 'w', encoding='utf-8') as f:
        f.write(result)
    print(f"wrote {out_path} ({len(result)} bytes)")

